  if(provider==='immowelt')return'Ich möchte keine Angabe machen';
  if(provider==='kleinanzeigen')return'Keine Angabe';
  return null;
 }
 if(provider==='kleinanzeigen'&&v==='TWO_ADULTS')return'Zweipersonenhaushalt';
 return HOUSEHOLD_LABELS[v]||null;
}
